import{_ as a,o as t,c as r,a2 as l}from"./chunks/framework.DnrXFDHb.js";const c=JSON.parse('{"title":"Transformer 直觉","description":"用直觉方式解释 Transformer 的注意力、位置表示、多头机制、残差连接和前馈网络如何协同处理序列。","frontmatter":{"description":"用直觉方式解释 Transformer 的注意力、位置表示、多头机制、残差连接和前馈网络如何协同处理序列。"},"headers":[],"relativePath":"llm/transformer.md","filePath":"llm/transformer.md","lastUpdated":1788308924000}'),n={name:"llm/transformer.md"};function i(o,e,s,d,h,p){return t(),r("div",null,[...e[0]||(e[0]=[l(`<h1 id="transformer-直觉" tabindex="-1">Transformer 直觉 <a class="header-anchor" href="#transformer-直觉" aria-label="Permalink to &quot;Transformer 直觉&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> Transformer 是现代大语言模型的核心架构，它用注意力机制让每个 Token 动态关注上下文里相关的部分，并支持并行计算，因此取代了 RNN 等早期序列模型。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已阅读 <a href="/llm/tokenization-embedding">Tokenization 与 Embedding</a>，知道文本会变成 Token 向量，也了解位置信息要单独处理。</li><li>不要求矩阵运算或微积分，本页的推演只用加权平均。</li><li>先接受一个边界：本页目标是建立直觉，不推导完整数学细节；真实的注意力在几十维以上的向量上做乘法，这里全部简化。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>用“检索匹配”的类比解释注意力机制（Query、Key、Value）在做什么。</li><li>说明多头注意力和多层堆叠各自增加什么能力。</li><li>解释为什么注意力机制还需要位置信息。</li><li>区分 Transformer 与 RNN 在处理方式上的差别。</li><li>判断关于 Transformer 的常见错误说法。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="为什么需要注意力-词义取决于上下文" tabindex="-1">为什么需要注意力：词义取决于上下文 <a class="header-anchor" href="#为什么需要注意力-词义取决于上下文" aria-label="Permalink to &quot;为什么需要注意力：词义取决于上下文&quot;">​</a></h3><p>语言不是逐词孤立理解的：</p><ul><li>“苹果”可能是水果，也可能是公司。</li><li>“它”指代谁，要看前文。</li><li>代码里同一个变量名的含义，取决于定义和调用位置。</li></ul><p>如果每个 Token 只有一个固定不变的向量，同一个词在不同语境里就无法区分。**注意力机制（Attention）**让每个 Token 根据上下文动态调整自己的表示，相当于把“词的含义由上下文决定”变成了可计算的过程。</p><h3 id="注意力怎么工作-查询、键、值" tabindex="-1">注意力怎么工作：查询、键、值 <a class="header-anchor" href="#注意力怎么工作-查询、键、值" aria-label="Permalink to &quot;注意力怎么工作：查询、键、值&quot;">​</a></h3><p>可以把每个 Token 想象成同时扮演三个角色：</p><ul><li><strong>查询（Query）</strong>：我在找什么信息。</li><li><strong>键（Key）</strong>：我能提供什么标签。</li><li><strong>值（Value）</strong>：我实际携带的内容。</li></ul><p>类比一次图书馆检索：Query 是你的搜索词，Key 是每本书的书脊标签，Value 是书的正文。搜索词和标签越匹配，这本书的正文在你的结果里占比越高。</p><p>**自注意力（Self-Attention）**把这个过程用在同一段输入内部，每个 Token 都会：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 用自己的 Query 和所有 Token 的 Key 比较，得到相关性分数</span></span>
<span class="line"><span>2. 把分数换算成权重（对一个查询，所有权重加起来等于 1）</span></span>
<span class="line"><span>3. 按权重加权平均所有 Token 的 Value</span></span>
<span class="line"><span>4. 得到融合了上下文的新表示</span></span></code></pre></div><p>最后一步的加权平均就是“信息流动”：权重越大，那个 Token 的信息进入当前 Token 新表示的比例越高。</p><p>这套相关性不是人工写死的规则，而是模型在训练中学出来的：真实模型里，Query、Key、Value 都是由可学习的参数矩阵从 Token 向量变换出来的，同一个 Token 在不同层、不同头里会得到不同的三件套。</p><h3 id="多头与多层-换个角度看-一层层加深" tabindex="-1">多头与多层：换个角度看，一层层加深 <a class="header-anchor" href="#多头与多层-换个角度看-一层层加深" aria-label="Permalink to &quot;多头与多层：换个角度看，一层层加深&quot;">​</a></h3><p>**多头注意力（Multi-Head Attention）**是把上面的过程并行做多次，每组独立的 Query、Key、Value 从不同角度观察上下文：</p><ul><li>一个头可能关注语法关系。</li><li>一个头可能关注指代关系。</li><li>一个头可能关注代码结构。</li><li>一个头可能关注格式边界。</li></ul><p>**多层堆叠（Layer）**则是把每一层注意力的输出再送进下一层，逐层精炼。底层可能更多处理相邻词、词性这类局部模式，高层更接近语义和任务相关的抽象表示。每过一层，“每个 Token 的表示”都被上下文更新一次。</p><p>Transformer 家族还有不同的形态：BERT 类模型是只读的编码器（encoder-only），擅长理解类任务；GPT 类对话模型是解码器（decoder-only），生成时使用带**因果掩码（Causal Mask）**的自注意力——每个 Token 只能看到它前面的 Token，这正是“根据前文预测下一个词”能够逐字进行的原因；完整的编码器-解码器结构则常见于翻译这类序列到序列任务。当前主流大语言模型基本都是 decoder-only 形态。</p><h3 id="位置信息与-transformer-为什么取代-rnn" tabindex="-1">位置信息与 Transformer 为什么取代 RNN <a class="header-anchor" href="#位置信息与-transformer-为什么取代-rnn" aria-label="Permalink to &quot;位置信息与 Transformer 为什么取代 RNN&quot;">​</a></h3><p>注意力本身对顺序不敏感：把输入 Token 的顺序打乱，不加位置信息的注意力计算结果基本不变。但语言强依赖顺序——“猫追狗”和“狗追猫”意思相反，代码、表格和列表也不能乱序。所以模型必须额外注入**位置编码（Positional Encoding）**或类似机制，告诉模型每个 Token 在序列中的位置（具体机制见 <a href="/llm/tokenization-embedding">Tokenization 与 Embedding</a>）。</p><p>在 Transformer（2017 年提出）之前，主流序列模型是 <strong>RNN（循环神经网络，Recurrent Neural Network）</strong>：逐个 Token 顺序处理，把前面的计算结果传给后面。它有两个短板：</p><ul><li>必须逐个计算，后一步依赖前一步，难以并行，训练慢。</li><li>远距离信息要一步步传递，容易被稀释，长程依赖很难学到。</li></ul><p>Transformer 用注意力让任意两个 Token 一步直连，距离不再衰减；整个序列可以并行计算，训练效率大幅提升。代价是注意力要求每对 Token 两两比较，计算量随序列长度增长得更快——这也是上下文窗口有限、长上下文成本高的一个原因。新的序列架构仍在演进，但当前主流大语言模型几乎都建立在 Transformer 之上。</p><h2 id="最小推演-手算三个词的注意力" tabindex="-1">最小推演：手算三个词的注意力 <a class="header-anchor" href="#最小推演-手算三个词的注意力" aria-label="Permalink to &quot;最小推演：手算三个词的注意力&quot;">​</a></h2><p>句子：<code>小猫 追 球</code>。假设已经算出三个 Token 之间的相关性（真实模型中这一步由训练出的参数计算），且每行加起来等于 1：</p><table tabindex="0"><thead><tr><th>查询 \\ 键</th><th style="text-align:right;">小猫</th><th style="text-align:right;">追</th><th style="text-align:right;">球</th></tr></thead><tbody><tr><td>小猫</td><td style="text-align:right;">0.1</td><td style="text-align:right;">0.4</td><td style="text-align:right;">0.5</td></tr><tr><td>追</td><td style="text-align:right;">0.5</td><td style="text-align:right;">0.1</td><td style="text-align:right;">0.4</td></tr><tr><td>球</td><td style="text-align:right;">0.4</td><td style="text-align:right;">0.3</td><td style="text-align:right;">0.3</td></tr></tbody></table><p>以“追”这一行为例：它作为查询时，对“小猫”权重 0.5、对自己 0.1、对“球”权重 0.4。再给三个 Token 随意设定玩具 Value 向量：小猫 <code>[1, 0]</code>、追 <code>[0, 1]</code>、球 <code>[0, 1]</code>，则“追”的新表示为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0.5 × [1, 0] + 0.1 × [0, 1] + 0.4 × [0, 1] = [0.5, 0.5]</span></span></code></pre></div><p>新表示里有一半信息来自“小猫”——动词“追”由此知道了自己的主语，也顺带吸收了宾语“球”的信息。用同样方法算“小猫”那一行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0.1 × [1, 0] + 0.4 × [0, 1] + 0.5 × [0, 1] = [0.1, 0.9]</span></span></code></pre></div><p>“小猫”的注意力重心同样落在了别的词上。注意力就是这样让信息在 Token 之间按权重流动，每个 Token 的新表示都由全句共同塑造。</p><p>这个推演只说明“按相关性加权汇总上下文”这一个步骤，不等于真实注意力——真实模型的相关性由训练学出的 Query、Key、Value 从高维向量计算得出，同一层还有多个头并行做这件事，并且整个过程逐层重复。</p><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><p>两种架构处理序列的方式截然不同：</p><table tabindex="0"><thead><tr><th>维度</th><th>RNN</th><th>Transformer</th></tr></thead><tbody><tr><td>处理方式</td><td>逐个 Token 顺序处理</td><td>整个序列并行计算</td></tr><tr><td>远距离信息</td><td>逐步传递，容易衰减</td><td>任意两个 Token 一步直连</td></tr><tr><td>训练效率</td><td>难以并行，训练慢</td><td>并行度高，训练快</td></tr><tr><td>顺序信息</td><td>按顺序读入，天然知道先后</td><td>注意力不认顺序，需要位置编码</td></tr><tr><td>长序列计算量</td><td>随长度近似线性增长</td><td>两两比较，随长度增长更快</td></tr></tbody></table><p>Transformer 并非全方位更优：长上下文的计算成本正是它的短板，但凭借并行和长程依赖两项优势，它成为当前大语言模型的主流选择。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“Attention 是在模仿人类注意力”</strong>：它只是一个加权汇总的数学机制，名字是类比，与人类的注意过程无关。</li><li><strong>“相关性和权重是人写死的”</strong>：Query、Key、Value 和相关性分数都来自训练学到的参数。</li><li><strong>“注意力天然知道词序”</strong>：不加位置信息时，注意力对顺序基本不敏感；顺序要靠位置编码等机制注入。</li><li><strong>“层数和头数越多一定越好”</strong>：收益会递减，成本会上升，效果还取决于数据质量与训练方法。</li><li><strong>“上下文越长效果一定越好”</strong>：注意力要在全部 Token 上分配权重，塞进来的无关内容会分走权重、稀释真正相关的信息，长上下文还需要检索、排序和压缩配合。</li><li><strong>“Transformer 能真正理解世界”</strong>：它学到的是可泛化的模式和表示，不自动保证事实正确。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-用图书馆检索类比-说明-query、key、value-分别对应什么" tabindex="-1">1. 用图书馆检索类比，说明 Query、Key、Value 分别对应什么？ <a class="header-anchor" href="#_1-用图书馆检索类比-说明-query、key、value-分别对应什么" aria-label="Permalink to &quot;1. 用图书馆检索类比，说明 Query、Key、Value 分别对应什么？&quot;">​</a></h3><details><summary>查看答案</summary><p>Query 对应你输入的搜索词，Key 对应每本书的书脊标签，Value 对应书的内容。搜索词与标签越匹配，这本书的正文在结果中占比越高；在注意力里，相关性越高，该 Token 的信息就越多地融入当前 Token 的新表示。</p></details><h3 id="_2-为什么-transformer-的训练比-rnn-快" tabindex="-1">2. 为什么 Transformer 的训练比 RNN 快？ <a class="header-anchor" href="#_2-为什么-transformer-的训练比-rnn-快" aria-label="Permalink to &quot;2. 为什么 Transformer 的训练比 RNN 快？&quot;">​</a></h3><details><summary>查看答案</summary><p>RNN 必须按顺序逐个 Token 计算，后一步依赖前一步的结果，难以并行；Transformer 的注意力对所有 Token 同时做两两比较，整个序列可以并行计算，训练效率大幅提高。</p></details><h3 id="_3-注意力机制为什么还需要位置编码" tabindex="-1">3. 注意力机制为什么还需要位置编码？ <a class="header-anchor" href="#_3-注意力机制为什么还需要位置编码" aria-label="Permalink to &quot;3. 注意力机制为什么还需要位置编码？&quot;">​</a></h3><details><summary>查看答案</summary><p>注意力计算本身对 Token 的先后顺序不敏感，打乱顺序结果基本不变；而语言、代码、表格都强依赖顺序，所以必须用位置编码或类似机制把位置信息注入模型。</p></details><h2 id="下一步阅读" tabindex="-1">下一步阅读 <a class="header-anchor" href="#下一步阅读" aria-label="Permalink to &quot;下一步阅读&quot;">​</a></h2><ul><li>上一篇：<a href="/llm/tokenization-embedding">Tokenization 与 Embedding</a>：先看文本如何变成向量，再看向量如何被注意力加工。</li><li>下一篇：<a href="/llm/inference-decoding">推理与解码</a>：理解模型如何逐 Token 生成内容，以及采样参数的真实作用。</li><li>相关阅读：<a href="/llm/basics">大模型入门</a>：把架构放回 LLM 的整体图景中。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">Vaswani 等：Attention Is All You Need</a>：提出 Transformer 与自注意力机制的经典论文。</li><li><a href="https://jalammar.github.io/illustrated-transformer/" target="_blank" rel="noreferrer">Jay Alammar：The Illustrated Transformer</a>：广为流传的图解文章，把注意力流程一步步画了出来。</li><li><a href="https://huggingface.co/learn/llm-course/chapter1/4" target="_blank" rel="noreferrer">Hugging Face LLM Course：How do Transformers work?</a>：官方课程中的架构概览章节。</li><li><a href="https://en.wikipedia.org/wiki/Transformer_%28machine_learning_model%29" target="_blank" rel="noreferrer">Wikipedia：Transformer</a>：架构的沿革、变种与影响概览。</li><li><a href="https://www.youtube.com/watch?v=kCc8FmEb1nY" target="_blank" rel="noreferrer">Karpathy：Let&#39;s build GPT: from scratch</a>：从零构建 GPT 的代码讲座，适合想深入实现细节的读者。</li></ul>`,56)])])}const m=a(n,[["render",i]]);export{c as __pageData,m as default};
